    (19, "الفاعل والمسند", "كل جملة إنجليزية تحتوي على فاعل ومسند. الفاعل هو من يقوم بالفعل، والمسند هو ما يُقال عن الفاعل.", "في جملة 'The dog runs fast'، 'The dog' هو الفاعل و'runs fast' هو المسند."),
    (20, "اللغة المجازية", "اللغة المجازية تستخدم الصور والتشبيهات لإيصال المعنى بطريقة إبداعية. أنواعها: التشبيه والاستعارة والتجسيد والمبالغة.", "في جملة 'Life is a journey'، الحياة تُشبَّه بالرحلة  -  هذه استعارة."),
    (21, "المفردات في السياق", "يمكنك فهم الكلمات الجديدة من خلال السياق المحيط بها في الجملة أو الفقرة دون الحاجة إلى قاموس.", "في جملة 'The famished boy ate everything on his plate'، كلمة 'famished' تعني جائعاً جداً."),
    (22, "الفكرة الرئيسية", "الفكرة الرئيسية هي الموضوع الأساسي للفقرة. الجمل الداعمة تقدم أدلة وتفاصيل تدعم هذه الفكرة.", "الجملة الأولى في الفقرة غالباً تحتوي على الفكرة الرئيسية وتسمى الجملة الموضوعية."),
    (23, "وجهة النظر", "وجهة النظر تحدد من يروي القصة. الأولى تستخدم 'I/me'، الثانية 'you'، الثالثة 'he/she/they'.", "في جملة 'I went to the store'، المتكلم يروي القصة  -  هذه وجهة النظر الأولى."),
    (24, "الهياكل النصية", "النصوص تُنظَّم بطرق مختلفة: المقارنة والتباين، السبب والنتيجة، المشكلة والحل، والتسلسل الزمني.", "نص يبدأ بـ'First... Then... Finally...' يستخدم هيكل التسلسل الزمني."),
    (25, "الكتابة السردية", "القصة السردية تحتوي على قوس قصصي: بداية ووسط ونهاية. الحوار يُكتب بين علامات تنصيص.", "البداية تقدم الشخصيات والمكان، الوسط يحتوي على الصراع، والنهاية تحل الصراع."),
    (26, "الشعر الإنجليزي", "الشعر يستخدم القافية والإيقاع والصور الشعرية. القافية ABAB تعني أن السطر الأول يقافي الثالث والثاني يقافي الرابع.", "التجانس الصوتي (Alliteration) هو تكرار صوت ساكن في بداية كلمات متجاورة مثل 'Peter Piper picked'."),
    (27, "الجمل المركبة", "الجمل المركبة تربط جملتين مستقلتين بأحرف العطف التنسيقية FANBOYS: for, and, nor, but, or, yet, so.", "في جملة 'I was tired, but I finished my homework'، 'but' يربط الجملتين."),
    (28, "المبني للمعلوم والمجهول", "في المبني للمعلوم الفاعل يقوم بالفعل. في المبني للمجهول الفاعل يتلقى الفعل.", "مبني للمعلوم: 'The cat chased the mouse.' مبني للمجهول: 'The mouse was chased by the cat.'"),
    (29, "الكتابة الإقناعية", "الكتابة الإقناعية تهدف إلى إقناع القارئ برأي ما. تستخدم الأطروحة والأدلة والنداءات المنطقية والعاطفية.", "Ethos = مصداقية الكاتب، Pathos = النداء العاطفي، Logos = النداء المنطقي بالأدلة."),
    (30, "الأساليب الأدبية", "الأساليب الأدبية تثري النص: الاستباق (foreshadowing)، السخرية (irony)، الرمزية (symbolism)، الموضوع (theme).", "الحمامة البيضاء ترمز للسلام  -  هذا مثال على الرمزية في الأدب."),
    (31, "هدف الكاتب", "الكاتب يكتب لأغراض ثلاثة: الإعلام أو الإقناع أو الترفيه. يمكن أن يكون النص منحازاً إذا قدّم جانباً واحداً فقط.", "مقال علمي يهدف إلى الإعلام، وإعلان تجاري يهدف إلى الإقناع."),
    (32, "البحث والاستشهاد", "البحث الجيد يعتمد على المصادر الموثوقة. الاستشهاد يعني الإشارة إلى المصدر لتجنب الانتحال الأدبي.", "تنسيق MLA للاستشهاد: اسم المؤلف، عنوان الكتاب، سنة النشر."),
    (33, "شكسبير والأدب الكلاسيكي", "شكسبير كتب مسرحياته بالخماسي الأيامبي (iambic pentameter). سوناتاته تحتوي على 14 سطراً.", "المأساة تنتهي بموت البطل، أما الكوميديا فتنتهي بالزواج أو الحل السعيد."),
    (34, "أصول الكلمات", "معرفة الجذور اللاتينية واليونانية تساعدك على فهم كلمات جديدة: bio=حياة، geo=أرض، port=حمل، dict=قول، scrib=كتابة.", "كلمة 'biology' من 'bio' (حياة) و'logy' (دراسة)  -  أي دراسة الحياة."),
    (35, "القواعد المتقدمة", "الفاصلة المنقوطة (;) تربط جملتين مستقلتين. النقطتان (:) تقدمان قائمة أو تفسيراً. البنية المتوازية تجعل الجمل متناسقة.", "مثال على البنية المتوازية: 'She likes reading, writing, and drawing'  -  كلها أفعال مضارعة.")
]

